package com.andye.warmod.silo;import com.andye.warmod.WarMod;import com.andye.warmod.antiair.*;import com.andye.warmod.block.*;import com.andye.warmod.block.entity.MissileSiloBlockEntity;import com.andye.warmod.icbm.*;import com.andye.warmod.item.component.TargetCoordinates;import java.util.*;import net.minecraft.SharedConstants;import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.world.level.ChunkPos;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;
public final class MissileSiloLaunchService{private static final Map<ServerLevel,LinkedHashMap<UUID,MissileSiloLaunchRequest>> PENDING=new WeakHashMap<>();private MissileSiloLaunchService(){}public static synchronized MissileSiloLaunchResult requestLaunch(ServerLevel l,MissileSiloBlockEntity silo,MissileSiloLaunchTrigger trigger,@Nullable UUID player,@Nullable String name,@Nullable TargetCoordinates override){if(silo.pendingLaunchRequestId()!=null||EnumSet.of(MissileSiloState.LAUNCHING,MissileSiloState.COOLDOWN,MissileSiloState.RELOADING).contains(silo.siloState()))return fail(MissileSiloLaunchFailure.BUSY,"Silo is busy");if(!MissileSiloStructure.isComplete(l,silo.getBlockPos(),silo.facing()))return fail(MissileSiloLaunchFailure.INVALID_STRUCTURE,"Silo structure is incomplete");SiloMissileType type=MissilePayloadItems.missileType(silo.missileStack()).orElse(null);if(type==null)return fail(MissileSiloLaunchFailure.NO_AMMUNITION,"Silo has no supported ammunition");if(type.role()==SiloMissileRole.INTERCEPTOR)return interceptor(l,silo,trigger,player,name,type);return strategic(l,silo,trigger,player,name,override,type);}
private static MissileSiloLaunchResult interceptor(ServerLevel l,MissileSiloBlockEntity silo,MissileSiloLaunchTrigger trigger,@Nullable UUID player,@Nullable String name,SiloMissileType type){if(!AntiAirFlightControllerManager.canAccept(l))return fail(MissileSiloLaunchFailure.INTERCEPTOR_CONTROLLER_REJECTED,"Interceptor controller limit reached");Vec3 origin=origin(silo);AntiAirTargetLock lock=AntiAirTargetSelector.acquire(l,origin).orElse(null);if(lock==null)return fail(MissileSiloLaunchFailure.NO_INTERCEPT_TARGET,"No eligible incoming strategic carrier");Vec3 burnout=AntiAirLaunchService.estimatedBurnout(l,origin);AntiAirInterceptSolution solution=AntiAirInterceptSolver.solve(burnout,l.getGameTime()+AntiAirConstants.IGNITION_TICKS+AntiAirConstants.BOOST_TICKS,lock).orElse(null);if(solution==null)return fail(MissileSiloLaunchFailure.INTERCEPT_NOT_FEASIBLE,"Target cannot be intercepted in time");UUID requestId=UUID.randomUUID();if(silo.reserveOne(requestId)==null)return fail(MissileSiloLaunchFailure.BUSY,"Silo is busy");int tier=MissileSiloGuidanceFrameStructure.installedTier(l,silo.getBlockPos(),silo.facing());var launch=AntiAirLaunchService.launchFromSilo(l,trigger==MissileSiloLaunchTrigger.REDSTONE?silo.ownerPlayerId():player,name==null?"SERVER":name,silo.siloId(),silo.getBlockPos(),origin,type.antiAirVariant().orElseThrow(),lock,solution,tier,collision(silo));if(launch.isEmpty()){silo.restoreReserved();return fail(MissileSiloLaunchFailure.INTERCEPTOR_CONTROLLER_REJECTED,"Interceptor controller rejected launch");}silo.launchAccepted(launch.get().flightPlan().interceptorId());notify(l,player,"Interceptor launch accepted");return MissileSiloLaunchResult.accepted(requestId);}
private static MissileSiloLaunchResult strategic(ServerLevel l,MissileSiloBlockEntity silo,MissileSiloLaunchTrigger trigger,@Nullable UUID player,@Nullable String name,@Nullable TargetCoordinates override,SiloMissileType type){var requests=PENDING.computeIfAbsent(l,x->new LinkedHashMap<>());if(requests.size()>=MissileSiloConstants.MAX_PENDING_LAUNCHES_PER_LEVEL)return fail(MissileSiloLaunchFailure.TOO_MANY_PENDING_LAUNCHES,"Too many pending silo launches");TargetCoordinates target=trigger==MissileSiloLaunchTrigger.REDSTONE?silo.storedTarget():override;if(target==null)target=silo.storedTarget();if(target==null||!target.isValid()||!target.dimension().equals(l.dimension())||!l.getWorldBorder().isWithinBounds(target.position())||l.isOutsideBuildHeight(net.minecraft.core.BlockPos.containing(target.position())))return fail(MissileSiloLaunchFailure.INVALID_TARGET,"Silo target is invalid");UUID id=UUID.randomUUID();if(silo.reserveOne(id)==null)return fail(MissileSiloLaunchFailure.BUSY,"Silo is busy");Set<ChunkPos> tickets=IcbmChunkTicketRegistry.window(IcbmChunkTicketRegistry.chunk(target.position()),2);IcbmChunkTicketRegistry.acquireAll(l,tickets);requests.put(id,new MissileSiloLaunchRequest(id,silo.siloId(),silo.getBlockPos(),trigger,player,name==null?"SERVER":name,type,target,null,null,l.getGameTime(),tickets));return MissileSiloLaunchResult.accepted(id);}
public static synchronized void tick(ServerLevel l){var requests=PENDING.get(l);if(requests==null)return;var it=requests.values().iterator();while(it.hasNext()){var r=it.next();var silo=l.getBlockEntity(r.siloCentre())instanceof MissileSiloBlockEntity s&&s.siloId().equals(r.siloId())?s:null;if(silo==null){release(l,r);it.remove();continue;}long waited=l.getGameTime()-r.creationGameTime();if(waited>=MissileSiloConstants.TARGET_PREPARATION_TIMEOUT_TICKS){release(l,r);silo.fail("Target area did not load");it.remove();continue;}if(!allLoaded(l,r.temporaryTickets()))continue;if(!MissileSiloStructure.isComplete(l,silo.getBlockPos(),silo.facing())){release(l,r);silo.fail("Silo structure changed");it.remove();continue;}int tier=MissileSiloGuidanceFrameStructure.installedTier(l,silo.getBlockPos(),silo.facing());UUID owner=r.trigger()==MissileSiloLaunchTrigger.REDSTONE?silo.ownerPlayerId():r.triggeringPlayerId();var result=IcbmLaunchService.launchFromSilo(l,owner,r.triggeringPlayerName(),origin(silo),r.strategicTarget().position(),r.missileType().payloadType().orElseThrow(),collision(silo),silo.siloId(),silo.getBlockPos(),tier);release(l,r);it.remove();if(result.isPresent()){silo.launchAccepted(result.get().flightPlan().missileId());notify(l,r.triggeringPlayerId(),"Missile launch accepted");}else{silo.fail("Flight plan could not be constructed");notify(l,r.triggeringPlayerId(),"Missile launch failed");}}if(requests.isEmpty())PENDING.remove(l);}
public static synchronized void cancel(ServerLevel l,UUID siloId,String reason){var m=PENDING.get(l);if(m==null)return;var it=m.values().iterator();while(it.hasNext()){var r=it.next();if(!r.siloId().equals(siloId))continue;release(l,r);if(l.getBlockEntity(r.siloCentre())instanceof MissileSiloBlockEntity s)s.fail(reason);it.remove();}if(m.isEmpty())PENDING.remove(l);}public static synchronized void stop(){for(var e:PENDING.entrySet())for(var r:e.getValue().values()){release(e.getKey(),r);if(e.getKey().getBlockEntity(r.siloCentre())instanceof MissileSiloBlockEntity s)s.restoreReserved();}PENDING.clear();}
private static Vec3 origin(MissileSiloBlockEntity s){return new Vec3(s.getBlockPos().getX()+.5,s.getBlockPos().getY()+1.4,s.getBlockPos().getZ()+.5);}private static MissileSiloCollisionContext collision(MissileSiloBlockEntity s){Set<net.minecraft.core.BlockPos> ignored=new LinkedHashSet<>(MissileSiloStructure.positions(s.getBlockPos(),s.facing()));ignored.addAll(MissileSiloGuidanceFrameStructure.positions(s.getBlockPos(),s.facing()));return new MissileSiloCollisionContext(s.siloId(),s.getBlockPos(),ignored,MissileSiloConstants.MISSILE_COLLISION_WIDTH,MissileSiloConstants.MISSILE_COLLISION_HEIGHT);}private static boolean allLoaded(ServerLevel l,Set<ChunkPos> p){for(var c:p)if(l.getChunkSource().getChunkNow(c.x(),c.z())==null)return false;return true;}private static void release(ServerLevel l,MissileSiloLaunchRequest r){IcbmChunkTicketRegistry.releaseAll(l,r.temporaryTickets());}private static MissileSiloLaunchResult fail(MissileSiloLaunchFailure f,String m){return MissileSiloLaunchResult.failed(f,m);}private static void notify(ServerLevel l,@Nullable UUID id,String m){if(id==null)return;ServerPlayer p=l.getServer().getPlayerList().getPlayer(id);if(p!=null)p.sendSystemMessage(Component.literal(m));}}